-- ---------- updated_at triggers ----------
do $$
declare t text;
begin
  foreach t in array array[
    'profiles', 'addresses', 'categories', 'collections', 'products', 'product_variants',
    'inventory', 'carts', 'cart_items', 'delivery_zones', 'coupons', 'orders',
    'payment_methods', 'payments', 'banners', 'hero_slides', 'homepage_sections',
    'reviews', 'pages', 'menus', 'site_settings', 'blog_posts'
  ] loop
    execute format(
      'create trigger set_updated_at before update on public.%I
         for each row execute function public.set_updated_at()', t);
  end loop;
end
$$;

-- ===== 20261103000003_functions_triggers.sql =====
-- VAYORA FASHION — 0003 functions and triggers
-- All SECURITY DEFINER functions pin search_path and fully qualify names.

-- ---------- role helpers ----------
create or replace function public.has_any_role(variadic roles public.app_role[])
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid() and ur.role = any (roles)
  );
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.user_roles ur where ur.user_id = auth.uid());
$$;

-- ---------- new user -> profile (never grants roles) ----------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text := nullif(new.raw_user_meta_data ->> 'phone', '');
begin
  if v_phone is not null and v_phone !~ '^01[3-9][0-9]{8}$' then
    v_phone := null; -- never let a bad value block sign-up
  end if;
  insert into public.profiles (id, full_name, phone)
  values (new.id, nullif(left(new.raw_user_meta_data ->> 'full_name', 120), ''), v_phone)
  on conflict (id) do nothing;
  return new;
end
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------- role safety ----------
-- The last super admin can never be removed (by anyone, including SQL editor users).
create or replace function public.protect_last_super_admin()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op in ('DELETE', 'UPDATE') and old.role = 'super_admin'
     and (tg_op = 'DELETE' or new.role <> 'super_admin' or new.user_id <> old.user_id) then
    if not exists (
      select 1 from public.user_roles
      where role = 'super_admin' and id <> old.id
    ) then
      raise exception 'Cannot remove the last super_admin';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;

create trigger protect_last_super_admin
  before update or delete on public.user_roles
  for each row execute function public.protect_last_super_admin();

create or replace function public.stamp_role_grant()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  return new;
end
$$;

create trigger stamp_role_grant
  before insert on public.user_roles
  for each row execute function public.stamp_role_grant();

-- ---------- inventory row per variant ----------
create or replace function public.create_inventory_for_variant()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.inventory (variant_id) values (new.id) on conflict do nothing;
  return new;
end
$$;

create trigger create_inventory_for_variant
  after insert on public.product_variants
  for each row execute function public.create_inventory_for_variant();

-- ---------- order numbers: VAY-YYMMDD-00001 (Asia/Dhaka date) ----------
create or replace function public.generate_order_number()
returns text
language sql
volatile
set search_path = ''
as $$
  select 'VAY-' || to_char(now() at time zone 'Asia/Dhaka', 'YYMMDD') || '-'
         || lpad(nextval('public.order_number_seq')::text, 5, '0');
$$;

alter table public.orders
  alter column order_number set default public.generate_order_number();

-- ---------- orders: financial integrity + history ----------
-- Signed-in browser clients (role "authenticated") can never alter money, identity
-- or routing columns, even if they have staff UPDATE access. Server code using the
-- service role, and SQL run by the project owner, are not restricted.
create or replace function public.guard_order_changes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'authenticated' and (
       new.order_number     is distinct from old.order_number
    or new.tracking_token   is distinct from old.tracking_token
    or new.user_id          is distinct from old.user_id
    or new.subtotal         is distinct from old.subtotal
    or new.discount_total   is distinct from old.discount_total
    or new.delivery_charge  is distinct from old.delivery_charge
    or new.total            is distinct from old.total
    or new.advance_amount   is distinct from old.advance_amount
    or new.cod_amount       is distinct from old.cod_amount
    or new.coupon_id        is distinct from old.coupon_id
    or new.coupon_code      is distinct from old.coupon_code
    or new.delivery_zone_id is distinct from old.delivery_zone_id
    or new.placed_at        is distinct from old.placed_at
  ) then
    raise exception 'Order financial and identity fields are immutable from the client';
  end if;
  return new;
end
$$;

create trigger guard_order_changes
  before update on public.orders
  for each row execute function public.guard_order_changes();

create or replace function public.record_order_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.order_status_history (order_id, from_status, to_status, changed_by)
    values (new.id, null, new.status, auth.uid());
  elsif new.status is distinct from old.status then
    insert into public.order_status_history (order_id, from_status, to_status, changed_by)
    values (new.id, old.status, new.status, auth.uid());
  end if;
  return new;
end
$$;

create trigger record_order_status_insert
  after insert on public.orders
  for each row execute function public.record_order_status();
create trigger record_order_status_update
  after update of status on public.orders
  for each row execute function public.record_order_status();

-- ---------- payments: clients cannot change verification state ----------
create or replace function public.guard_payment_changes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Inside verify_payment() (SECURITY DEFINER) current_user is the function owner;
  -- a direct client UPDATE runs as the API role, which cannot be spoofed.
  if current_user in ('authenticated', 'anon') then
    raise exception 'Payments can only be verified or rejected through verify_payment()';
  end if;
  return new;
end
$$;

create trigger guard_payment_changes
  before update on public.payments
  for each row execute function public.guard_payment_changes();

-- ---------- admin activity log ----------
create or replace function public.log_admin_action(
  p_action text,
  p_entity_type text default null,
  p_entity_id text default null,
  p_details jsonb default '{}'
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_staff() then
    raise exception 'Not authorised';
  end if;
  insert into public.admin_activity_logs (actor_id, action, entity_type, entity_id, details)
  values (auth.uid(), left(p_action, 120), left(p_entity_type, 60), left(p_entity_id, 120), coalesce(p_details, '{}'));
end
$$;

-- ---------- manual payment verification (the only path to "verified") ----------
create or replace function public.verify_payment(
  p_payment_id uuid,
  p_approve boolean,
  p_reason text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_pay public.payments;
begin
  if not public.has_any_role('super_admin', 'admin', 'payment_manager') then
    raise exception 'Not authorised';
  end if;

  select * into v_pay from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'Payment not found';
  end if;
  if v_pay.status <> 'submitted' then
    raise exception 'Only submitted payments can be verified or rejected (current: %)', v_pay.status;
  end if;
  if not p_approve and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'A rejection reason is required';
  end if;

  if p_approve then
    update public.payments
       set status = 'verified', verified_by = auth.uid(), verified_at = now(), rejection_reason = null
     where id = p_payment_id;
    update public.orders
       set status = 'confirmed'
     where id = v_pay.order_id and status = 'pending_payment_verification';
  else
    update public.payments
       set status = 'rejected', verified_by = auth.uid(), verified_at = now(),
           rejection_reason = left(trim(p_reason), 500)
     where id = p_payment_id;
  end if;

  insert into public.admin_activity_logs (actor_id, action, entity_type, entity_id, details)
  values (auth.uid(),
          case when p_approve then 'payment.verified' else 'payment.rejected' end,
          'payment', p_payment_id::text,
          jsonb_build_object('order_id', v_pay.order_id, 'amount', v_pay.amount, 'reason', p_reason));
end
$$;

-- ---------- stock (server-side only: Edge Functions with the service role) ----------
create or replace function public.reserve_stock(p_variant_id uuid, p_qty integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_qty is null or p_qty <= 0 then raise exception 'Quantity must be positive'; end if;
  update public.inventory
     set reserved = reserved + p_qty
   where variant_id = p_variant_id and quantity - reserved >= p_qty;
  if not found then
    raise exception 'Insufficient stock for variant %', p_variant_id;
  end if;
end
$$;

create or replace function public.release_stock(p_variant_id uuid, p_qty integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_qty is null or p_qty <= 0 then raise exception 'Quantity must be positive'; end if;
  update public.inventory set reserved = greatest(reserved - p_qty, 0) where variant_id = p_variant_id;
end
$$;

-- Permanently deduct (e.g. when an order ships): consumes the reservation.
create or replace function public.commit_stock(p_variant_id uuid, p_qty integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_qty is null or p_qty <= 0 then raise exception 'Quantity must be positive'; end if;
  update public.inventory
     set quantity = quantity - p_qty, reserved = reserved - p_qty
   where variant_id = p_variant_id and reserved >= p_qty and quantity >= p_qty;
  if not found then
    raise exception 'Cannot commit % units for variant %', p_qty, p_variant_id;
  end if;
end
$$;

-- ---------- function privileges ----------
revoke execute on function public.reserve_stock(uuid, integer) from public, anon, authenticated;
revoke execute on function public.release_stock(uuid, integer) from public, anon, authenticated;
revoke execute on function public.commit_stock(uuid, integer) from public, anon, authenticated;
grant execute on function public.reserve_stock(uuid, integer) to service_role;
grant execute on function public.release_stock(uuid, integer) to service_role;
grant execute on function public.commit_stock(uuid, integer) to service_role;

revoke execute on function public.verify_payment(uuid, boolean, text) from public, anon;
grant execute on function public.verify_payment(uuid, boolean, text) to authenticated;
revoke execute on function public.log_admin_action(text, text, text, jsonb) from public, anon;
grant execute on function public.log_admin_action(text, text, text, jsonb) to authenticated;

-- ===== 20261103000004_rls.sql =====
-- VAYORA FASHION — 0004 row level security
--
-- Model
--   * Public storefront data: read-only for everyone, active/published rows only.
--   * Private customer data: owner-only.
--   * Staff access is by role (checked in the database, not just the UI):
--       catalogue  -> super_admin, admin, product_manager
--       orders     -> super_admin, admin, order_manager (+ payment_manager read)
--       payments   -> read: super_admin, admin, payment_manager, order_manager
--                     verify/reject: verify_payment() only
--       content    -> super_admin, admin
--       roles      -> super_admin only
--   * There is NO anonymous write access anywhere. Orders, payments, newsletter
--     and contact submissions are created by Edge Functions (service role) that
--     validate input, recalculate money and rate-limit (later phases).

-- Defence in depth: the API roles get no destructive privileges they never need.
revoke insert, update, delete, truncate on all tables in schema public from anon;
revoke truncate on all tables in schema public from authenticated;
revoke usage, select, update on all sequences in schema public from anon, authenticated;

do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end
$$;

-- ---------- roles ----------
create policy "read own roles" on public.user_roles
  for select to authenticated
  using (user_id = auth.uid() or public.has_any_role('super_admin'));
create policy "super admin grants roles" on public.user_roles
  for insert to authenticated
  with check (public.has_any_role('super_admin'));
create policy "super admin changes roles" on public.user_roles
  for update to authenticated
  using (public.has_any_role('super_admin'))
  with check (public.has_any_role('super_admin'));
create policy "super admin revokes roles" on public.user_roles
  for delete to authenticated
  using (public.has_any_role('super_admin'));

-- ---------- profiles & addresses ----------
create policy "own profile read" on public.profiles
  for select to authenticated using (id = auth.uid());
create policy "staff read profiles" on public.profiles
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager'));
create policy "own profile update" on public.profiles
  for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

create policy "own addresses" on public.addresses
  for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "staff read addresses" on public.addresses
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager'));

-- ---------- catalogue: public read ----------
create policy "public read categories" on public.categories
  for select to anon, authenticated using (is_active);
create policy "public read collections" on public.collections
  for select to anon, authenticated using (is_active);
create policy "public read products" on public.products
  for select to anon, authenticated using (status = 'active');
create policy "public read product collections" on public.product_collections
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));
create policy "public read product images" on public.product_images
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));
create policy "public read variants" on public.product_variants
  for select to anon, authenticated
  using (is_active and exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));

-- ---------- catalogue: staff write (product managers and above) ----------
do $$
declare t text;
begin
  foreach t in array array[
    'categories', 'collections', 'products', 'product_collections',
    'product_images', 'product_variants', 'inventory'
  ] loop
    execute format(
      'create policy "catalogue staff all" on public.%I for all to authenticated
         using (public.has_any_role(''super_admin'', ''admin'', ''product_manager''))
         with check (public.has_any_role(''super_admin'', ''admin'', ''product_manager''))', t);
  end loop;
end
$$;

-- Inventory is not public. Storefront reads availability through this view,
-- which exposes only a capped figure (never exact stock or reservations).
create view public.variant_availability as
  select i.variant_id,
         (i.quantity - i.reserved) > 0 as in_stock,
         least(greatest(i.quantity - i.reserved, 0), 10) as available_qty
    from public.inventory i
    join public.product_variants v on v.id = i.variant_id and v.is_active
    join public.products p on p.id = v.product_id and p.status = 'active';
grant select on public.variant_availability to anon, authenticated;

-- ---------- cart & wishlist (owner only) ----------
create policy "own cart" on public.carts
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own cart items" on public.cart_items
  for all to authenticated
  using (exists (select 1 from public.carts c where c.id = cart_id and c.user_id = auth.uid()))
  with check (exists (select 1 from public.carts c where c.id = cart_id and c.user_id = auth.uid()));
create policy "own wishlist" on public.wishlists
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own wishlist items" on public.wishlist_items
  for all to authenticated
  using (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = auth.uid()))
  with check (exists (select 1 from public.wishlists w where w.id = wishlist_id and w.user_id = auth.uid()));

-- ---------- delivery, coupons ----------
create policy "public read active zones" on public.delivery_zones
  for select to anon, authenticated using (is_active);
create policy "admin all zones" on public.delivery_zones
  for all to authenticated
  using (public.has_any_role('super_admin', 'admin'))
  with check (public.has_any_role('super_admin', 'admin'));

-- Coupons are never readable by customers (codes would leak); validated server-side.
create policy "admin all coupons" on public.coupons
  for all to authenticated
  using (public.has_any_role('super_admin', 'admin'))
  with check (public.has_any_role('super_admin', 'admin'));
create policy "admin read coupon usages" on public.coupon_usages
  for select to authenticated using (public.has_any_role('super_admin', 'admin'));

-- ---------- orders (created only by Edge Functions) ----------
create policy "own orders" on public.orders
  for select to authenticated using (user_id = auth.uid());
create policy "staff read orders" on public.orders
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager', 'payment_manager'));
create policy "staff update orders" on public.orders
  for update to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager'))
  with check (public.has_any_role('super_admin', 'admin', 'order_manager'));

create policy "own order items" on public.order_items
  for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy "staff read order items" on public.order_items
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager', 'payment_manager'));

create policy "own order history" on public.order_status_history
  for select to authenticated
  using (is_public and exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy "staff read order history" on public.order_status_history
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager', 'payment_manager'));

-- ---------- payments ----------
create policy "own payments" on public.payments
  for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));
create policy "staff read payments" on public.payments
  for select to authenticated
  using (public.has_any_role('super_admin', 'admin', 'order_manager', 'payment_manager'));
-- no insert/update policies: payments are written by Edge Functions and verify_payment()

-- Merchant numbers are meant to be shown to customers who must pay; only enabled
-- methods are exposed. Only admins and payment managers can change them.
create policy "public read enabled payment methods" on public.payment_methods
  for select to anon, authenticated using (is_enabled);
create policy "payment staff manage methods" on public.payment_methods
  for all to authenticated
  using (public.has_any_role('super_admin', 'admin', 'payment_manager'))
  with check (public.has_any_role('super_admin', 'admin', 'payment_manager'));

-- ---------- storefront content ----------
create policy "public read banners" on public.banners
  for select to anon, authenticated
  using (is_active and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));
create policy "public read hero slides" on public.hero_slides
  for select to anon, authenticated
  using (is_active and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));
create policy "public read homepage sections" on public.homepage_sections
  for select to anon, authenticated using (is_enabled);
create policy "public read published pages" on public.pages
  for select to anon, authenticated using (is_published);
create policy "public read active menus" on public.menus
  for select to anon, authenticated using (is_active);
create policy "public read public settings" on public.site_settings
  for select to anon, authenticated using (is_public);
create policy "public read published posts" on public.blog_posts
  for select to anon, authenticated using (is_published and (published_at is null or published_at <= now()));

do $$
declare t text;
begin
  foreach t in array array[
    'banners', 'hero_slides', 'homepage_sections', 'pages', 'menus', 'site_settings', 'blog_posts'
  ] loop
    execute format(
      'create policy "admin all" on public.%I for all to authenticated
         using (public.has_any_role(''super_admin'', ''admin''))
         with check (public.has_any_role(''super_admin'', ''admin''))', t);
  end loop;
end
$$;

-- ---------- reviews ----------
create policy "public read approved reviews" on public.reviews
  for select to anon, authenticated using (status = 'approved');
create policy "own reviews read" on public.reviews
  for select to authenticated using (user_id = auth.uid());
create policy "customers write pending reviews" on public.reviews
