-- ===== 20261104000001_storefront_views.sql =====
-- VAYORA FASHION — 0007 storefront read models (Phase 4)
--
-- These views are owned by the migration role, so they can read inventory and
-- profiles that anonymous visitors cannot, while exposing ONLY what the public
-- storefront needs:
--   * active products only (drafts/inactive/archived never appear)
--   * stock as a boolean (never exact quantities or reservations)
--   * reviewer first name only (never email, phone, or full name)
-- Supabase's linter flags "security definer view" for these: that is intentional.

create or replace view public.storefront_products as
select
  p.id,
  p.slug,
  p.sku,
  p.name,
  p.short_description,
  p.description,
  p.gender,
  p.regular_price,
  p.selling_price,
  case when p.regular_price > 0 and p.selling_price < p.regular_price
       then round((p.regular_price - p.selling_price) / p.regular_price * 100)::int
       else 0 end as discount_pct,
  p.is_featured,
  p.is_bestseller,
  p.is_new_arrival,
  p.is_trending,
  p.sales_count,
  p.seo_title,
  p.seo_description,
  p.created_at,
  c.slug  as category_slug,
  c.name  as category_name,
  pc.slug as parent_category_slug,
  sc.slug as subcategory_slug,
  img.url  as image_url,
  img2.url as hover_image_url,
  coalesce(v.sizes, '{}'::text[])   as sizes,
  coalesce(v.colors, '[]'::jsonb)   as colors,
  coalesce(v.in_stock, false)       as in_stock,
  coalesce(r.review_count, 0)::int  as review_count,
  r.avg_rating,
  coalesce(col.slugs, '{}'::text[]) as collection_slugs
from public.products p
left join public.categories c  on c.id  = p.category_id
left join public.categories pc on pc.id = c.parent_id
left join public.categories sc on sc.id = p.subcategory_id
left join lateral (
  select i.url from public.product_images i
  where i.product_id = p.id
  order by i.is_main desc, i.sort_order, i.created_at
  limit 1
) img on true
left join lateral (
  select i.url from public.product_images i
  where i.product_id = p.id
  order by i.is_main desc, i.sort_order, i.created_at
  offset 1 limit 1
) img2 on true
left join lateral (
  select array_agg(distinct vv.size) filter (where vv.size is not null) as sizes,
         jsonb_agg(distinct jsonb_build_object('name', vv.color, 'hex', vv.color_hex))
           filter (where vv.color is not null) as colors,
         bool_or(coalesce(inv.quantity - inv.reserved, 0) > 0) as in_stock
  from public.product_variants vv
  left join public.inventory inv on inv.variant_id = vv.id
  where vv.product_id = p.id and vv.is_active
) v on true
left join lateral (
  select count(*) as review_count, round(avg(rv.rating), 1) as avg_rating
  from public.reviews rv
  where rv.product_id = p.id and rv.status = 'approved'
) r on true
left join lateral (
  select array_agg(co.slug) as slugs
  from public.product_collections pcx
  join public.collections co on co.id = pcx.collection_id and co.is_active
  where pcx.product_id = p.id
) col on true
where p.status = 'active';

-- read-only for every API role (Supabase grants new views ALL by default)
revoke all on public.storefront_products from anon, authenticated;
grant select on public.storefront_products to anon, authenticated;

create or replace view public.public_reviews as
select
  r.id,
  r.product_id,
  r.rating,
  r.title,
  r.comment,
  r.created_at,
  coalesce(nullif(split_part(trim(pr.full_name), ' ', 1), ''), 'Customer') as reviewer_name
from public.reviews r
left join public.profiles pr on pr.id = r.user_id
where r.status = 'approved'
  and exists (select 1 from public.products p where p.id = r.product_id and p.status = 'active');

revoke all on public.public_reviews from anon, authenticated;
grant select on public.public_reviews to anon, authenticated;

-- same hardening for the stock-flag view created in 0004
revoke all on public.variant_availability from anon, authenticated;
grant select on public.variant_availability to anon, authenticated;

-- ===== 20261104000007_catalog_functions.sql =====
-- VAYORA FASHION — 0007 catalogue functions (Phase 4)
--
-- list_products   : storefront search/filter/sort/pagination, done in the database so
--                   it scales to unlimited products. SECURITY DEFINER only so that the
--                   "in stock" filter can consult inventory; it returns product IDs and a
--                   total count, never stock figures, and only for ACTIVE products.
-- catalog_facets  : sizes / colours / price range available for the filter UI.
-- duplicate_product, set_main_image : atomic admin operations with role checks.

create or replace function public.list_products(
  p_gender public.gender_type default null,
  p_category text default null,
  p_collection text default null,
  p_q text default null,
  p_min_price numeric default null,
  p_max_price numeric default null,
  p_sizes text[] default null,
  p_colors text[] default null,
  p_in_stock boolean default false,
  p_new_only boolean default false,
  p_on_sale boolean default false,
  p_sort text default 'latest',
  p_limit integer default 24,
  p_offset integer default 0
)
returns table (product_id uuid, total_count bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(trim(coalesce(p_q, '')), '');
  v_like text;
  v_sizes boolean := coalesce(cardinality(p_sizes), 0) > 0;
  v_colors boolean := coalesce(cardinality(p_colors), 0) > 0;
begin
  if v_q is not null then
    v_like := '%' || replace(replace(replace(left(v_q, 80), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  return query
  with cat as (
    select c.id
      from public.categories c
     where p_category is not null
       and c.is_active
       and (c.slug = p_category
            or c.parent_id in (select c2.id from public.categories c2 where c2.slug = p_category))
  ),
  filtered as (
    select p.*
      from public.products p
     where p.status = 'active'
       and (p_gender is null or p.gender = p_gender or p.gender = 'unisex')
       and (p_category is null
            or p.category_id in (select id from cat)
            or p.subcategory_id in (select id from cat))
       and (p_collection is null or case p_collection
              when 'new-arrivals' then p.is_new_arrival
              when 'best-sellers' then p.is_bestseller
              when 'trending' then p.is_trending
              when 'featured' then p.is_featured
              when 'special-offers' then p.selling_price < p.regular_price
              else exists (
                select 1
                  from public.product_collections pc
                  join public.collections c on c.id = pc.collection_id
                 where pc.product_id = p.id and c.slug = p_collection and c.is_active)
            end)
       and (v_q is null
            or p.name ilike v_like
            or p.sku ilike v_like
            or coalesce(p.short_description, '') ilike v_like
            or exists (select 1 from public.categories c
                        where c.id in (p.category_id, p.subcategory_id) and c.name ilike v_like))
       and (p_min_price is null or p.selling_price >= p_min_price)
       and (p_max_price is null or p.selling_price <= p_max_price)
       and (not p_new_only or p.is_new_arrival)
       and (not p_on_sale or p.selling_price < p.regular_price)
       and (
         (not v_sizes and not v_colors and not p_in_stock)
         or exists (
           select 1
             from public.product_variants v
             left join public.inventory i on i.variant_id = v.id
            where v.product_id = p.id
              and v.is_active
              and (not v_sizes or v.size = any (p_sizes))
              and (not v_colors or v.color = any (p_colors))
              and (not p_in_stock or coalesce(i.quantity - i.reserved, 0) > 0)
         )
       )
  )
  select f.id, count(*) over ()
    from filtered f
   order by
     case when p_sort = 'price_asc' then f.selling_price end asc,
     case when p_sort = 'price_desc' then f.selling_price end desc,
     case when p_sort = 'best_selling' then f.sales_count end desc,
     case when p_sort = 'popular'
          then f.sales_count + case when f.is_trending then 1000000 else 0 end end desc,
     f.created_at desc,
     f.id
   limit least(greatest(coalesce(p_limit, 24), 1), 100)
  offset greatest(coalesce(p_offset, 0), 0);
end
$$;

revoke execute on function public.list_products(public.gender_type, text, text, text, numeric, numeric, text[], text[], boolean, boolean, boolean, text, integer, integer) from public;
grant execute on function public.list_products(public.gender_type, text, text, text, numeric, numeric, text[], text[], boolean, boolean, boolean, text, integer, integer) to anon, authenticated, service_role;

-- Facets use RLS-visible rows only (active products, active variants).
create or replace function public.catalog_facets()
returns jsonb
language sql
stable
set search_path = ''
as $$
  select jsonb_build_object(
    'sizes', coalesce((
      select jsonb_agg(distinct v.size)
        from public.product_variants v join public.products p on p.id = v.product_id
       where v.size is not null and v.is_active and p.status = 'active'), '[]'::jsonb),
    'colors', coalesce((
      select jsonb_agg(distinct jsonb_build_object('name', v.color, 'hex', v.color_hex))
        from public.product_variants v join public.products p on p.id = v.product_id
       where v.color is not null and v.is_active and p.status = 'active'), '[]'::jsonb),
    'min_price', (select min(selling_price) from public.products where status = 'active'),
    'max_price', (select max(selling_price) from public.products where status = 'active')
  );
$$;

revoke execute on function public.catalog_facets() from public;
grant execute on function public.catalog_facets() to anon, authenticated, service_role;

-- ---------- admin: duplicate a product (as a DRAFT, with zero stock) ----------
create or replace function public.duplicate_product(p_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  p public.products;
  v_new uuid;
  v_suffix text := substr(md5(random()::text || clock_timestamp()::text), 1, 5);
begin
  if not public.has_any_role('super_admin', 'admin', 'product_manager') then
    raise exception 'Not authorised';
  end if;
  select * into p from public.products where id = p_id;
  if not found then
    raise exception 'Product not found';
  end if;

  insert into public.products (
    slug, sku, name, short_description, description, category_id, subcategory_id, gender,
    regular_price, selling_price, status, is_featured, is_bestseller, is_new_arrival, is_trending,
    seo_title, seo_description)
  values (
    p.slug || '-copy-' || v_suffix, p.sku || '-C' || upper(v_suffix), p.name || ' (Copy)',
    p.short_description, p.description, p.category_id, p.subcategory_id, p.gender,
    p.regular_price, p.selling_price, 'draft', p.is_featured, p.is_bestseller, p.is_new_arrival,
    p.is_trending, p.seo_title, p.seo_description)
  returning id into v_new;

  insert into public.product_images (product_id, url, alt, sort_order, is_main)
    select v_new, url, alt, sort_order, is_main from public.product_images where product_id = p_id;
  insert into public.product_collections (product_id, collection_id)
    select v_new, collection_id from public.product_collections where product_id = p_id;
  insert into public.product_variants (product_id, sku, size, color, color_hex, price, is_active)
    select v_new, sku || '-C' || upper(v_suffix), size, color, color_hex, price, is_active
      from public.product_variants where product_id = p_id;

  insert into public.admin_activity_logs (actor_id, action, entity_type, entity_id, details)
  values (auth.uid(), 'product.duplicated', 'product', v_new::text, jsonb_build_object('source', p_id));
  return v_new;
end
$$;

-- ---------- admin: atomically choose the main image ----------
create or replace function public.set_main_image(p_image_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_product uuid;
begin
  if not public.has_any_role('super_admin', 'admin', 'product_manager') then
    raise exception 'Not authorised';
  end if;
  select product_id into v_product from public.product_images where id = p_image_id;
  if not found then
    raise exception 'Image not found';
  end if;
  update public.product_images set is_main = false where product_id = v_product and is_main and id <> p_image_id;
  update public.product_images set is_main = true where id = p_image_id;
end
$$;

revoke execute on function public.duplicate_product(uuid) from public, anon;
revoke execute on function public.set_main_image(uuid) from public, anon;
grant execute on function public.duplicate_product(uuid) to authenticated;
grant execute on function public.set_main_image(uuid) to authenticated;

-- ===== 20261105000001_checkout.sql =====
-- Phase 5: server-side cart pricing, coupons and order placement.
-- Additive and safe on a project that already has Phases 2-4 applied.
--
--   quote_order()  public, read-only: prices a cart from the database (never from the browser)
--   place_order()  service_role only: called by the `place-order` Edge Function; atomically
--                  re-prices, validates coupon + stock, reserves stock and writes the order.

alter table public.orders add column if not exists idempotency_key text;
create unique index if not exists orders_idempotency_idx
  on public.orders (idempotency_key) where idempotency_key is not null;

-- ---------- internal pricing engine ----------
create or replace function public._quote(
  p_items jsonb, p_district text, p_coupon text, p_user_id uuid, p_phone text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_lines jsonb;
  v_subtotal numeric(12, 2);
  v_all_ok boolean;
  v_discount numeric(12, 2) := 0;
  v_zone record;
  v_zone_id uuid;
  v_zone_name text;
  v_dmin integer;
  v_dmax integer;
  v_coupon_id uuid;
  v_coupon record;
  v_charge numeric(12, 2) := 0;
  v_free boolean := false;
  v_coupon_err text;
  v_delivery_err text;
  v_adv boolean;
  v_code text := upper(trim(coalesce(p_coupon, '')));
  v_ok boolean;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 50 then
    raise exception 'Your cart is empty or invalid.';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_items) e
    where jsonb_typeof(e) <> 'object'
       or coalesce(e ->> 'variant_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or case when coalesce(e ->> 'quantity', '') ~ '^[0-9]{1,2}$' then (e ->> 'quantity')::int else 0 end not between 1 and 50
  ) then
    raise exception 'Your cart is empty or invalid.';
  end if;

  with req as (
    select (e ->> 'variant_id')::uuid as vid, least(sum((e ->> 'quantity')::int), 50)::int as qty
    from jsonb_array_elements(p_items) e
    group by 1
  ),
  l as (
    select r.vid, r.qty, p.id as pid, p.name, p.slug, v.sku, v.size, v.color,
           coalesce(v.price, p.selling_price) as price,
           greatest(coalesce(i.quantity, 0) - coalesce(i.reserved, 0), 0) as avail,
           (v.id is not null and v.is_active and p.status = 'active') as sellable,
           (select im.url from public.product_images im where im.product_id = p.id
             order by im.is_main desc, im.sort_order limit 1) as img
    from req r
    left join public.product_variants v on v.id = r.vid
    left join public.products p on p.id = v.product_id
    left join public.inventory i on i.variant_id = v.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'variant_id', vid, 'product_id', pid, 'product_name', coalesce(name, 'Unavailable item'),
           'slug', slug, 'sku', sku, 'size', size, 'color', color, 'image_url', img,
           'unit_price', case when sellable then price else 0 end,
           'quantity', qty,
           'line_total', case when sellable then price * qty else 0 end,
           'available', case when sellable then avail else 0 end,
           'status', case when not sellable then 'unavailable' when avail < qty then 'insufficient' else 'ok' end
         ) order by name, size, color), '[]'::jsonb),
         coalesce(sum(case when sellable and avail >= qty then price * qty end), 0),
         coalesce(bool_and(sellable and avail >= qty), false)
    into v_lines, v_subtotal, v_all_ok
  from l;

  -- coupon
  if v_code <> '' then
    select * into v_coupon from public.coupons where code = v_code;
    if not found then
      v_coupon_err := 'This coupon is not valid.';
    elsif not v_coupon.is_active
       or (v_coupon.starts_at is not null and v_coupon.starts_at > now())
       or (v_coupon.expires_at is not null and v_coupon.expires_at <= now())
       or (v_coupon.usage_limit is not null and v_coupon.used_count >= v_coupon.usage_limit) then
      v_coupon_err := 'This coupon is not valid.';
    elsif v_subtotal < v_coupon.min_order_value then
      v_coupon_err := 'This coupon needs a minimum order of ৳' || trim(to_char(v_coupon.min_order_value, 'FM999999990.##')) || '.';
    elsif v_coupon.per_customer_limit is not null and (
      select count(*) from public.coupon_usages cu
      where cu.coupon_id = v_coupon.id
        and ((p_user_id is not null and cu.user_id = p_user_id) or (p_phone is not null and cu.phone = p_phone))
    ) >= v_coupon.per_customer_limit then
      v_coupon_err := 'You have already used this coupon.';
    else
      v_coupon_id := v_coupon.id;
      if v_coupon.type = 'percentage' then
        v_discount := round(v_subtotal * v_coupon.value / 100, 2);
        if v_coupon.max_discount is not null then v_discount := least(v_discount, v_coupon.max_discount); end if;
      else
        v_discount := v_coupon.value;
      end if;
      v_discount := least(v_discount, v_subtotal);
    end if;
  end if;

  -- delivery zone: highest priority active zone that lists the district, or an all-districts zone
  if nullif(trim(coalesce(p_district, '')), '') is not null then
    select * into v_zone
    from public.delivery_zones z
    where z.is_active
      and (cardinality(z.districts) = 0
           or lower(trim(p_district)) = any (select lower(d) from unnest(z.districts) d))
    order by z.priority desc, z.sort_order, z.created_at
    limit 1;
    if not found then
      v_delivery_err := 'We do not deliver to this district yet.';
    else
      v_zone_id := v_zone.id; v_zone_name := v_zone.name;
      v_dmin := v_zone.estimated_days_min; v_dmax := v_zone.estimated_days_max;
      v_charge := v_zone.charge;
      if v_zone.free_delivery_threshold is not null and v_subtotal - v_discount >= v_zone.free_delivery_threshold then
        v_charge := 0;
        v_free := true;
      end if;
    end if;
  end if;

  v_adv := coalesce((select value = 'true'::jsonb from public.site_settings where key = 'delivery_advance_required'), false)
           and v_charge > 0;
  v_ok := v_all_ok and v_coupon_err is null and v_delivery_err is null;

  return jsonb_build_object(
    'ok', v_ok,
    'lines', v_lines,
    'subtotal', v_subtotal,
    'discount_total', case when v_coupon_err is null then v_discount else 0 end,
    'delivery_charge', v_charge,
    'free_delivery', v_free,
    'delivery_zone_id', v_zone_id,
    'delivery_zone_name', v_zone_name,
    'estimated_days_min', v_dmin,
    'estimated_days_max', v_dmax,
    'delivery_error', v_delivery_err,
    'coupon_code', case when v_code <> '' and v_coupon_err is null then v_code else null end,
    'coupon_id', case when v_code <> '' and v_coupon_err is null then v_coupon_id else null end,
    'coupon_error', v_coupon_err,
    'total', v_subtotal - case when v_coupon_err is null then v_discount else 0 end + v_charge,
    'advance_required', v_adv
  );
end
$$;

-- ---------- public quote (read-only) ----------
create or replace function public.quote_order(
  p_items jsonb, p_district text default null, p_coupon text default null, p_phone text default null
) returns jsonb
language sql
security definer
set search_path = ''
as $$
  select (public._quote(p_items, p_district, p_coupon, auth.uid(), p_phone)) - 'coupon_id';
$$;

-- ---------- order placement (Edge Function only) ----------
create or replace function public.place_order(
  p_user_id uuid, p_customer jsonb, p_items jsonb, p_coupon text,
  p_expected_total numeric default null, p_idempotency_key text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c jsonb := coalesce(p_customer, '{}'::jsonb);
  v_name text := trim(coalesce(c ->> 'name', ''));
  v_phone text := coalesce(c ->> 'phone', '');
  v_alt text := nullif(coalesce(c ->> 'alt_phone', ''), '');
  v_email text := nullif(trim(coalesce(c ->> 'email', '')), '');
  v_district text := trim(coalesce(c ->> 'district', ''));
  v_area text := trim(coalesce(c ->> 'area', ''));
  v_address text := trim(coalesce(c ->> 'address', ''));
  v_instr text := nullif(trim(coalesce(c ->> 'delivery_instructions', '')), '');
  v_notes text := nullif(trim(coalesce(c ->> 'notes', '')), '');
  v_guest_ok boolean;
  v_q jsonb;
  v_line jsonb;
  v_status public.order_status := 'pending_order_review';
  v_status_setting text;
  v_order public.orders;
  v_existing public.orders;
  v_code text := upper(trim(coalesce(p_coupon, '')));
begin
  if p_idempotency_key is not null then
    if p_idempotency_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'Invalid request.';
    end if;
    select * into v_existing from public.orders where idempotency_key = p_idempotency_key;
    if found then
      return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number,
        'tracking_token', v_existing.tracking_token, 'subtotal', v_existing.subtotal,
        'discount_total', v_existing.discount_total, 'delivery_charge', v_existing.delivery_charge,
        'total', v_existing.total, 'advance_amount', v_existing.advance_amount,
        'cod_amount', v_existing.cod_amount, 'status', v_existing.status, 'duplicate', true);
    end if;
  end if;

  v_guest_ok := coalesce((select value = 'true'::jsonb from public.site_settings where key = 'allow_guest_checkout'), true);
  if p_user_id is null and not v_guest_ok then
    raise exception 'Please sign in to place an order.';
  end if;

  if length(v_name) < 2 or length(v_name) > 120 then raise exception 'Enter your full name.'; end if;
  if v_phone !~ '^01[3-9][0-9]{8}$' then raise exception 'Enter a valid Bangladeshi mobile number.'; end if;
  if v_alt is not null and v_alt !~ '^01[3-9][0-9]{8}$' then raise exception 'The alternative phone number is not valid.'; end if;
  if v_email is not null and (length(v_email) > 200 or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then raise exception 'Enter a valid email address.'; end if;
  if v_district = '' then raise exception 'Select your district.'; end if;
  if length(v_area) < 2 or length(v_area) > 120 then raise exception 'Enter your area.'; end if;
  if length(v_address) < 5 or length(v_address) > 300 then raise exception 'Enter your full delivery address.'; end if;
  if length(coalesce(v_instr, '')) > 500 or length(coalesce(v_notes, '')) > 500 then raise exception 'Notes are too long (max 500 characters).'; end if;

  -- serialise concurrent use of the same coupon so usage limits cannot be exceeded
  if v_code <> '' then
    perform 1 from public.coupons where code = v_code for update;
  end if;

  v_q := public._quote(p_items, v_district, v_code, p_user_id, v_phone);

  if v_q ->> 'delivery_error' is not null then raise exception '%', v_q ->> 'delivery_error'; end if;
  if v_q ->> 'coupon_error' is not null then raise exception '%', v_q ->> 'coupon_error'; end if;
  if not (v_q ->> 'ok')::boolean then
    raise exception 'Some items are no longer available in the quantity you chose. Please review your cart.';
  end if;
  if (v_q ->> 'advance_required')::boolean then
    raise exception 'Advance delivery-charge payment is not available yet. Please try again later.';
  end if;
  if p_expected_total is not null and p_expected_total <> (v_q ->> 'total')::numeric then
    raise exception 'Prices changed. Please review your updated total.';
  end if;

  select value #>> '{}' into v_status_setting from public.site_settings where key = 'order_status_without_advance';
  if v_status_setting in ('pending_order_review', 'confirmed') then v_status := v_status_setting::public.order_status; end if;

  -- reserve stock (atomic: any failure rolls the whole order back)
  begin
    for v_line in select * from jsonb_array_elements(v_q -> 'lines') loop
      perform public.reserve_stock((v_line ->> 'variant_id')::uuid, (v_line ->> 'quantity')::int);
    end loop;
  exception when others then
    raise exception 'Some items just went out of stock. Please review your cart.';
  end;

  insert into public.orders (
    user_id, customer_name, phone, alt_phone, email, district, area, address,
    delivery_instructions, notes, delivery_zone_id, coupon_id, coupon_code,
    subtotal, discount_total, delivery_charge, total, advance_amount, cod_amount, status, idempotency_key
  ) values (
    p_user_id, v_name, v_phone, v_alt, v_email, v_district, v_area, v_address,
    v_instr, v_notes, nullif(v_q ->> 'delivery_zone_id', '')::uuid, nullif(v_q ->> 'coupon_id', '')::uuid,
    v_q ->> 'coupon_code',
    (v_q ->> 'subtotal')::numeric, (v_q ->> 'discount_total')::numeric, (v_q ->> 'delivery_charge')::numeric,
    (v_q ->> 'total')::numeric, 0, (v_q ->> 'total')::numeric, v_status, p_idempotency_key
  ) returning * into v_order;

  insert into public.order_items (order_id, product_id, variant_id, product_name, sku, size, color, image_url, unit_price, quantity, line_total)
  select v_order.id, (l ->> 'product_id')::uuid, (l ->> 'variant_id')::uuid, l ->> 'product_name', l ->> 'sku',
         l ->> 'size', l ->> 'color', l ->> 'image_url', (l ->> 'unit_price')::numeric, (l ->> 'quantity')::int,
         (l ->> 'line_total')::numeric
  from jsonb_array_elements(v_q -> 'lines') l;

  if v_q ->> 'coupon_id' is not null then
    insert into public.coupon_usages (coupon_id, order_id, user_id, phone, discount_amount)
    values ((v_q ->> 'coupon_id')::uuid, v_order.id, p_user_id, v_phone, v_order.discount_total);
    update public.coupons set used_count = used_count + 1 where id = (v_q ->> 'coupon_id')::uuid;
  end if;

  return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number,
    'tracking_token', v_order.tracking_token, 'subtotal', v_order.subtotal,
    'discount_total', v_order.discount_total, 'delivery_charge', v_order.delivery_charge,
    'total', v_order.total, 'advance_amount', v_order.advance_amount,
    'cod_amount', v_order.cod_amount, 'status', v_order.status, 'duplicate', false);
end
$$;

-- ---------- privileges ----------
revoke all on function public._quote(jsonb, text, text, uuid, text) from public, anon, authenticated;
revoke all on function public.quote_order(jsonb, text, text, text) from public;
grant execute on function public.quote_order(jsonb, text, text, text) to anon, authenticated;
revoke all on function public.place_order(uuid, jsonb, jsonb, text, numeric, text) from public, anon, authenticated;
grant execute on function public.place_order(uuid, jsonb, jsonb, text, numeric, text) to service_role;
